<?php
require_once dirname(__DIR__).'/app/bootstrap.php';require_role(['teacher','admin']);$user=current_user();$errors=[];
if(is_post()){verify_csrf();$action=(string)($_POST['action']??'');if($action==='announce'){$title=trim((string)($_POST['title']??''));$body=trim((string)($_POST['body']??''));$audience=(string)($_POST['audience']??'learner');$pinned=isset($_POST['is_pinned'])?1:0;if(mb_strlen($title)<4)$errors['title']='Use a clear announcement title.';if(mb_strlen($body)<10)$errors['body']='Write a complete announcement message.';if(!in_array($audience,['all','learner','teacher'],true))$errors['audience']='Select a valid audience.';if(!$errors){Database::query("INSERT INTO announcements (author_id,title,body,audience,status,is_pinned,published_at) VALUES (?,?,?,?, 'published',?,CURRENT_TIMESTAMP)",[$user['id'],$title,$body,$audience,$pinned]);activity('announcement_published',['title'=>$title]);flash('success','The announcement was published.');redirect('teacher/dashboard.php');}}if($action==='delete_announcement'){$id=request_int('announcement_id');$params=[$id];$sql='DELETE FROM announcements WHERE id=?';if($user['role']!=='admin'){$sql.=' AND author_id=?';$params[]=(int)$user['id'];}Database::query($sql,$params);activity('announcement_deleted',['announcement_id'=>$id]);flash('success','The announcement was removed.');redirect('teacher/dashboard.php');}}
$stats=Learning::teacherOverview();
$learners=Database::fetchAll("SELECT u.id,u.name,u.username,u.school_name,u.points,u.last_login_at,COUNT(DISTINCT CASE WHEN p.status='completed' THEN p.lesson_id END) AS completed_lessons,COALESCE(ROUND(AVG(CASE WHEN p.best_score>0 THEN p.best_score END)),0) AS average_score,COUNT(DISTINCT pr.id) AS project_count FROM users u LEFT JOIN progress p ON p.user_id=u.id LEFT JOIN projects pr ON pr.user_id=u.id WHERE u.role='learner' AND u.status='active' GROUP BY u.id ORDER BY u.last_login_at DESC,u.name LIMIT 50");
$difficult=Database::fetchAll("SELECT l.title,l.slug,c.title AS course_title,COUNT(qa.id) AS attempts,COALESCE(ROUND(AVG(qa.score)),0) AS average_score FROM lessons l JOIN courses c ON c.id=l.course_id LEFT JOIN quiz_attempts qa ON qa.lesson_id=l.id GROUP BY l.id HAVING COUNT(qa.id)>0 ORDER BY average_score ASC,attempts DESC LIMIT 6");
$announcements=Database::fetchAll('SELECT * FROM announcements WHERE author_id=? ORDER BY created_at DESC LIMIT 8',[$user['id']]);
$pageTitle='Teacher centre';$bodyClass='teacher-page';require base_path('partials/header.php');
?>
<section class="workspace-section page-intro"><div><span class="eyebrow">Teaching operations</span><h1>Teacher centre</h1><p>Review engagement, identify difficult lessons, inspect learner progress and publish guidance.</p></div><button class="button" type="button" data-modal-open="announcement-modal"><?= icon('plus') ?>New announcement</button></section>
<section class="metric-grid four"><article class="metric-card"><span class="metric-icon purple"><?= icon('users') ?></span><div><small>Active learners</small><strong><?= $stats['learners'] ?></strong></div></article><article class="metric-card"><span class="metric-icon blue"><?= icon('chart') ?></span><div><small>Active this week</small><strong><?= $stats['active_week'] ?></strong></div></article><article class="metric-card"><span class="metric-icon green"><?= icon('check-circle') ?></span><div><small>Completed lessons</small><strong><?= $stats['completed'] ?></strong></div></article><article class="metric-card"><span class="metric-icon orange"><?= icon('trophy') ?></span><div><small>Average quiz score</small><strong><?= $stats['average'] ?>%</strong></div></article></section>
<div class="management-grid"><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Learner monitoring</span><h2>Current learner performance</h2></div><div class="search-field compact"><?= icon('search') ?><input aria-label="Search learners" data-filter-input data-filter-target=".learner-table-row"></div></div><div class="data-table learner-table"><div class="data-table-head"><span>Learner</span><span>Lessons</span><span>Average</span><span>Projects</span><span>Last active</span><span></span></div><?php foreach($learners as $learner): ?><a class="data-table-row learner-table-row" data-filter-item href="<?= e(url('teacher/learner.php?id='.(int)$learner['id'])) ?>"><span class="person-cell"><span class="avatar small"><?= e(initials($learner['name'])) ?></span><span><strong><?= e($learner['name']) ?></strong><small><?= e($learner['school_name']) ?></small></span></span><span data-label="Lessons"><?= (int)$learner['completed_lessons'] ?></span><span data-label="Average"><?= (int)$learner['average_score'] ?>%</span><span data-label="Projects"><?= (int)$learner['project_count'] ?></span><span data-label="Last active"><?= e(time_ago($learner['last_login_at'])) ?></span><?= icon('arrow-right') ?></a><?php endforeach; ?><?php if(!$learners): ?><div class="compact-empty">Learner accounts will appear after registration.</div><?php endif; ?></div></section><aside><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Assessment insight</span><h2>Lessons needing attention</h2></div></div><?php if($difficult): ?><div class="difficulty-list"><?php foreach($difficult as $lesson): ?><a href="<?= e(url('lesson.php?lesson='.urlencode($lesson['slug']))) ?>"><span class="score-badge <?= (int)$lesson['average_score']>=60?'success':'warning' ?>"><?= (int)$lesson['average_score'] ?>%</span><span><strong><?= e($lesson['title']) ?></strong><small><?= e($lesson['course_title']) ?> · <?= (int)$lesson['attempts'] ?> attempts</small></span><?= icon('arrow-right') ?></a><?php endforeach; ?></div><?php else: ?><div class="compact-empty">Assessment insight appears after learners submit quizzes.</div><?php endif; ?></section><section class="panel"><div class="panel-heading"><div><span class="eyebrow">Published by you</span><h2>Recent announcements</h2></div></div><div class="mini-notice-list"><?php foreach($announcements as $notice): ?><article><span><strong><?= e($notice['title']) ?></strong><small><?= e(ucfirst($notice['audience'])) ?> · <?= e(time_ago($notice['created_at'])) ?></small></span><form method="post" data-confirm="Remove this announcement?"><?= csrf_field() ?><input type="hidden" name="action" value="delete_announcement"><input type="hidden" name="announcement_id" value="<?= (int)$notice['id'] ?>"><button class="icon-button danger" type="submit" aria-label="Delete <?= e($notice['title']) ?>"><?= icon('trash') ?></button></form></article><?php endforeach; ?><?php if(!$announcements): ?><div class="compact-empty">You have not published an announcement.</div><?php endif; ?></div></section></aside></div>
<dialog class="modal" id="announcement-modal" data-modal><div class="modal-card"><div class="modal-head"><div><span class="eyebrow">Communication</span><h2>Publish announcement</h2></div><button class="icon-button" type="button" data-modal-close aria-label="Close announcement form"><?= icon('x') ?></button></div><form method="post" class="form-stack"><?= csrf_field() ?><input type="hidden" name="action" value="announce"><div class="field"><label for="announcement-title">Title</label><input id="announcement-title" name="title" required><?= validation_error($errors,'title') ?></div><div class="field"><label for="announcement-body">Message</label><textarea id="announcement-body" name="body" rows="5" required></textarea><?= validation_error($errors,'body') ?></div><div class="field"><label for="announcement-audience">Audience</label><select id="announcement-audience" name="audience"><option value="learner">Learners</option><option value="teacher">Teachers</option><option value="all">Everyone</option></select></div><label class="consent-check"><input type="checkbox" name="is_pinned"><span>Pin this announcement above newer notices</span></label><div class="modal-actions"><button class="button button-secondary" type="button" data-modal-close>Cancel</button><button class="button" type="submit">Publish announcement</button></div></form></div></dialog>
<?php require base_path('partials/footer.php'); ?>
